/* ↓ 在这儿写 pick_biggest 这一招：
   ① 三份投喂：那一排碗、碗的只数、还有外面那张牌的门牌号
   ② 绕鱼干跑圈找出最大那只碗，记下它的位子
   ③ 把那只碗的门牌号挂到外面那张牌上（剥一层往里写） */

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
